  export type HookCategory = keyof typeof HOOK_LIBRARY;

  export const HOOK_CATEGORY_LABELS: Record<HookCategory, string> = {
    hormozi: "Alex Hormozi (proven viral)",
    hundredFormulas: "100 Hook Formulas",
    educational: "Educational",
    storytelling: "Storytelling",
    question: "Question-Based",
    curiosity: "Curiosity-Driven",
    listBased: "List-Based",
    problemSolving: "Problem-Solving",
    relatable: "Relatable",
    tipsTricks: "Tips & Tricks",
  };

  // Build a compact prompt block - cap per-category so we don't blow the context
  // window. We pick a deterministic spread (every Nth) so the model sees the full
  // stylistic range, not just the first N.
  export function getHookLibraryForPrompt(opts?: { perCategory?: number }): string {
    const cap = opts?.perCategory ?? 35;
    const parts: string[] = [];
    for (const cat of Object.keys(HOOK_LIBRARY) as HookCategory[]) {
      const all = HOOK_LIBRARY[cat] as readonly string[];
      const step = Math.max(1, Math.floor(all.length / cap));
      const sample: string[] = [];
      for (let i = 0; i < all.length && sample.length < cap; i += step) sample.push(all[i]);
      parts.push(`### ${HOOK_CATEGORY_LABELS[cat]} (${cat})\n` + sample.map((h, i) => `${i + 1}. ${h}`).join("\n"));
    }
    return parts.join("\n\n");
  }

